import{_ as a,c as t,o,ag as r}from"./chunks/framework.BXxQSk_p.js";const g=JSON.parse('{"title":"ADR 002: Add GroundAtlas Project-Control Gate","description":"","frontmatter":{},"headers":[],"relativePath":"adr/002-groundatlas-project-control-gate.md","filePath":"adr/002-groundatlas-project-control-gate.md"}'),n={name:"adr/002-groundatlas-project-control-gate.md"};function d(s,e,i,c,l,u){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-002-add-groundatlas-project-control-gate" tabindex="-1">ADR 002: Add GroundAtlas Project-Control Gate <a class="header-anchor" href="#adr-002-add-groundatlas-project-control-gate" aria-label="Permalink to &quot;ADR 002: Add GroundAtlas Project-Control Gate&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>WebGPU is a public production native package. It already has native build, test, Release, OIDC, and npm registry readback boundaries, but it did not expose a vendor-neutral project manifest or dogfood the released GroundAtlas package/action.</p><p>The project-control surface must not make <code>.doctrine/project.json</code> a public default and must not make generated <code>.groundatlas*</code> reports authoritative. This change must not alter native WebGPU behavior, package exports, platform package artifacts, runtime tests, release artifacts, or compatibility claims.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Add:</p><ul><li>a vendor-neutral <code>project.manifest.json</code>;</li><li>a single CI <code>groundatlas</code> job using <code>SylphxAI/groundatlas@v0.1.2</code> with <code>groundatlas@0.1.2</code>;</li><li>assertions that GroundAtlas selects <code>project.manifest.json</code>, reports <code>.doctrine/project.json</code> only as an adapter, and has zero strict fleet warnings/blockers;</li><li>a small Node project-control boundary test;</li><li><code>needs: groundatlas</code> on the native build matrix plus an explicit failure step so existing build contexts are gated without duplicating GroundAtlas across every platform target.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>GroundAtlas package/action dogfooding gates the existing native build matrix.</li><li><code>.doctrine/project.json</code> remains the Sylphx Doctrine adapter and local governance catalog.</li><li>Release proof remains the existing Release workflow plus <code>release:readback</code> and npm registry readback for changed packages.</li><li>Generated <code>.groundatlas*</code> reports remain evidence/navigation only.</li></ul>',11)])])}const h=a(n,[["render",d]]);export{g as __pageData,h as default};
